; INIT: cold start. Program the 8251 USART (mode 0DAH = async x16, 7 data, odd parity,
; 2 stop; command 37H = TxEN DTR RxE ER RTS), set SP, program both 8155s and the 8279,
; SIM 1DH = enable RST 6.5 only, clear RAM 6F00-70FB, read the front-panel switches,
; derive SLOT_COUNT from the GRI and fall into the acquisition sequence.
INIT:
        MVI A,0DAH
        STA USART_CTRL              ; 8251 mode: async x16, 7 data bits, odd parity, 2 stop bits
        LXI SP,STACK_TOP
        CALL PULSE_PB2
        MVI A,0CDH
D_0080       EQU  $+1
        STA KDC_CMD                 ; 8279: clear display and FIFO (CD=110 CA=1)
        MVI A,0D0H
        STA PIO1_TMRLO              ; 8155#1 timer = 07D0H (2000), square wave
        MVI A,47H                   ; 'G'
        STA PIO1_TMRHI
        MVI A,0CFH
        STA PIO1_CMD                ; 8155#1: PA out, PB out, PC out, start timer
        MVI A,82H
        STA PIO2_TMRLO              ; 8155#2 timer = 0082H (130) -> 1200 baud x16
        MVI A,40H                   ; '@'
        STA PIO2_TMRHI
        MVI A,0C3H
        STA PIO2_CMD                ; 8155#2: PA out, PB out, PC input, start timer
        MVI A,8EH
        STA PIO2_PB                 ; 8155#2 port B idle pattern 8EH
        MVI A,37H                   ; '7'
        STA USART_CTRL              ; 8251 command: TxEN DTR RxE ER RTS
        MVI A,1DH
        SIM                         ; SIM 1DH: mask 5.5 & 7.5, enable 6.5, reset 7.5 latch
        MVI A,04H
        STA KDC_CMD                 ; 8279 mode: 8x8 display, encoded scan sensor matrix
        MVI A,26H                   ; '&'
        STA KDC_CMD                 ; 8279 clock prescaler = 6
        MVI A,90H
        STA KDC_CMD                 ; 8279: write display RAM, auto-increment, addr 0
        CALL X_1E4C
        MVI A,20H                   ; ' '
        CALL PULSE_PB
        MVI B,00H
        LXI H,RAM1_BASE
        CALL FILL_ZERO              ; clear 6F00-6FFF
        MVI B,0FCH
        LXI H,RAM2_BASE
        CALL FILL_ZERO              ; clear 7000-70FB (keeps return address at 70FE)
