        SUI 0AH
        JP INIT_DIV10
        MOV A,E
        STA SLOT_COUNT              ; SLOT_COUNT = 4 + (A-40)/10 + 1
        MOV B,A
        LXI H,FIRST_SLOT
        MVI M,01H
        XCHG
        LHLD SEL_A
        MOV A,L                     ; L = SEL_A, H = SEL_B
        CMP B
        JP INIT_CHK_SELB
        STA FIRST_SLOT
        PUSH B
        PUSH H
        CALL X_1DBD
        POP H
        POP B
INIT_CHK_SELB:
        LDA SEL_B
        CMP B
        JP ACQ_START
        CMP L
        JZ ACQ_START
