; ACQ_START: (re)start master acquisition. Reached again whenever tracking is lost.
ACQ_START:
        CALL CPY_GRI_TO_TOA
        LXI H,CUR_TOA
        CALL TOA_TO_BIN
        SUI 05H
        STA WIN_END
        MVI A,0EH
        CALL X_0DB3
        LXI H,CUR_REC
        LXI B,REC_MASTER
        CALL COPY4
        LXI H,BCD_K_00080980
        CALL X_0EC1
        MVI A,0EH
        CALL X_0DB3
        LXI H,CUR_REC
        LXI B,REC_SEC
        CALL COPY4
SEARCH_RESTART:
        CALL RESET_PULSES
        LXI B,REC_MASTER

; SEARCH_LOOP: search for the master phase code, alternating REC_MASTER / REC_SEC targets.
SEARCH_LOOP:
        CALL X_0DE6
        CALL WAIT_EPOCH
        CALL WAIT_SAMPLE
        XRA A
        STA SAMPLE_CNT
        CALL X_0ED9
        CALL FIRST_SAMPLE
        STC
        CALL MATCH_PULSES
        JNC SEARCH_VERIFY
        LDA CUR_NPULSE
        CPI 00H
        LXI B,REC_MASTER
        JNZ SEARCH_NEXT
        LXI B,REC_SEC
SEARCH_NEXT:
        JMP SEARCH_LOOP
SEARCH_VERIFY:
        CALL SAMPLE_TO_BCD
        CALL CPY_GRI_TO_TOA
        LXI H,BCD_DELTA_2
        CALL X_0EC1
        MVI A,0FH
        CALL X_0D79
        CALL WAIT_EPOCH
        CALL WAIT_SAMPLE
