        PUSH PSW
        MOV D,A
        MVI C,0AH
        CALL MUL8                   ; BC = SLOT_IDX * 10
        MVI A,10H
        ADD C
        STA WIN_END
        MOV A,C
        STA CUR_NPULSE
        POP PSW
        PUSH PSW
        DCR A
        JZ SLOT_CHK_NEXT
        CALL GET_FLAGS_A
        RLC
        JNC SLOT_CHK_NEXT
        RAR
        CALL SEC_TOA_TO_BIN
        ADI 0AH
        STA CUR_NPULSE
SLOT_CHK_NEXT:
        POP PSW
        INR A
        LXI H,SLOT_COUNT
        CMP M
        JNZ SLOT_CHK_NEXT2
        JMP TRACK_NEXT_SLOT
SLOT_USE_GRI:
        LXI H,GRI_BCD
        CALL TOA_TO_BIN
        SUI 04H
        STA WIN_END
        MVI A,82H
        STA MISS_LIMIT
        JMP SLOT_WIN_CALC
SLOT_CHK_NEXT2:
        INR A
        CMP M
        JZ SLOT_USE_GRI
        DCR A
        CALL GET_FLAGS_A
        RLC
        JNC SLOT_WIN_CALC
        RAR
        CALL SEC_TOA_TO_BIN
        SUI 04H
        STA WIN_END
SLOT_WIN_CALC:
        LDA CUR_NPULSE
        MOV B,A
        LXI H,WIN_END
        SUB M
        CMA
        INR A
        INR A
        MOV M,A
        CPI 09H
        JM TRACK_NEXT_SLOT
        MOV A,B
        CALL BCD_INC_STORE
        STA PULSE_BCD
        CALL COUNT_TRACKED
        LXI H,CUR_FLAGS
        MOV A,M
        ORA B
        MOV M,A
        LXI H,BCD_DELTA_2
        CALL CPY4_TO_TOA
        XRA A
        STA MISS_CNT
        CALL RESET_PULSES
        MVI A,80H
        STA TRACK_STATE
SLOT_DONE_06:
        MVI A,06H
SLOT_DONE:
        STA CUR_REC
SLOT_SAVE_NEXT:
        CALL SAVE_CUR_REC
        JMP TRACK_NEXT_SLOT

; SLOT_TRACKING: state 80H. Verify the pulse group; count misses (MISS_CNT / MISS_LIMIT).
SLOT_TRACKING:
        CALL WAIT_SAMPLE
        CALL X_0E2D
        CALL FIRST_SAMPLE
        STC
        CMC
        CALL MATCH_PULSES
        PUSH PSW
        LDA SYNC_FLAG
        RRC
        JC SLOT_TRK_RESULT
        CALL PULSE_PB2
        CALL X_0E1D
        MVI A,20H                   ; ' '
        CALL PULSE_PB
SLOT_TRK_RESULT:
        POP PSW
        JNC SLOT_TRK_LOST
        LDA CUR_NPULSE
        CPI 00H
        JNZ SLOT_TRK_END
SLOT_TRK_MISS:
        LXI H,BCD_K_00000110
        CALL X_0EC1
        LXI H,MISS_CNT
        INR M
        LDA MISS_LIMIT
        CMP M
        JNZ SLOT_TRK_END
        XRA A
        MOV M,A
        LXI H,TOA_ALT
        CALL CPY4_TO_TOA
SLOT_TRK_END:
        JMP SLOT_DONE_06
SLOT_TRK_LOST:
        MVI A,40H                   ; '@'
        STA TRACK_STATE
        CALL CLEAR_PULSES
        LXI B,TOA_SAVE
        LXI H,CUR_TOA
        CALL COPY4
        LDA CUR_TOA_1
        CALL BCD_TO_BIN
        SUI 09H
        LXI H,SAMPLE_CNT
        ADD M
        CALL BIN_TO_BCD
        STA CUR_TOA_1
SLOT_MODE3:
        MVI A,03H
        STA CUR_MODE
        MVI A,07H
        JMP SLOT_DONE

; SLOT_ACQUIRE: state 40H. Read the phase code, accumulate pulse counts, decide lock (state 80H).
SLOT_ACQUIRE:
        XRA A
        STA SAMPLE_CNT
        CALL WAIT_SAMPLE
        CALL X_0E1A
        CALL READ_PHASE
        LDA PHASE_CODE
        LXI H,CUR_NPULSE
        CALL COUNT_BITS4
        PUSH PSW
        MOV A,B
        ADD M
        MOV M,A
        POP PSW
        INX H
        CALL COUNT_BITS4
        MOV A,B
        ADD M
        MOV M,A
        INX H
        INR M
        MOV A,M
        CPI 04H
        JNZ SLOT_ACQ_CHK8
        CALL CHK_NPULSE
        JC SLOT_ACQ_FAIL
        JMP SLOT_SAVE_NEXT
SLOT_ACQ_CHK8:
        CPI 08H
        JNZ SLOT_SAVE_NEXT
        CALL CHK_NPULSE
        JNC SLOT_ACQ_OK
SLOT_ACQ_FAIL:
        MVI A,80H
        STA TRACK_STATE
        CALL RESET_PULSES
        LXI H,TOA_SAVE
        CALL CPY4_TO_TOA
        JMP SLOT_TRK_MISS
SLOT_ACQ_OK:
        CALL X_1E05
        STA SLOT_RESULT
        LXI H,ACQ_COUNT
        INR M
        MOV A,M
        CPI 01H
        JNZ SLOT_ACQ_FLAGS
        LDA SLOT_IDX
        STA FIRST_SLOT
SLOT_ACQ_FLAGS:
        LDA CUR_FLAGS
        PUSH PSW
        CALL BIT_OF_STA
        ORA M
        MOV M,A
        POP PSW
        ORI 0C0H
        STA CUR_FLAGS
        MVI A,01H
        STA NEW_DATA
        CALL CLEAR_PULSES
        JMP SLOT_MODE3

; QUAL_UPDATE: count zero bits in each nibble of PHASE_CODE into QUAL_LO/QUAL_HI (saturate at 40H).
QUAL_UPDATE:
        LDA PHASE_CODE
        CMA
        LHLD QUAL_LO
        MVI E,04H
QUAL_LO_LOOP:
        RRC
        JNC QUAL_LO_NEXT
        INR L
QUAL_LO_NEXT:
        DCR E
        JNZ QUAL_LO_LOOP
        PUSH PSW
        MOV A,L
        CPI 40H                     ; '@'
        JC QUAL_HI_START
        MVI L,40H                   ; '@'
QUAL_HI_START:
        POP PSW
        MVI E,04H
QUAL_HI_LOOP:
        RRC
        JNC QUAL_HI_NEXT
        INR H
QUAL_HI_NEXT:
        DCR E
        JNZ QUAL_HI_LOOP
        MOV A,H
        CPI 40H                     ; '@'
        JC QUAL_STORE
        MVI H,40H                   ; '@'
QUAL_STORE:
        SHLD QUAL_LO
        RET

; QUAL_CHECK: carry set if either QUAL counter < 28H (poor signal).
QUAL_CHECK:
        LHLD QUAL_LO
        MOV A,L
        CPI 28H                     ; '('
        JC QUAL_BAD
        MOV A,H
        CPI 28H                     ; '('
        JC QUAL_BAD
        STC
        CMC
        RET
QUAL_BAD:
        STC
        RET

; WAIT_SAMPLE: idle/background loop. Opens a one-instruction interrupt window (EI NOP DI);
; when RST 6.5 fires the ISR returns directly to WAIT_SAMPLE's caller (see RST65_ISR).
; Between windows: optional expansion ROM hook at 2000H (signature 0A5H), serial receive,
; serial transmit, and, if RST 7.5 latched (RIM bit 6), the periodic tick tasks.
WAIT_SAMPLE:
        EI                          ; one-instruction window for RST 6.5
        NOP
        DI
        PUSH PSW
        PUSH D
        LDA EXTROM_SIG              ; expansion ROM present if 2000H = 0A5H
        CPI 0A5H
        CZ EXTROM_ENTRY
        CALL SERIAL_POLL
        CALL TX_SERVICE
        RIM
        ANI 40H                     ; RIM bit 6 = RST 7.5 pending
        JZ WAIT_SAMPLE_END
        LDA PIO1_PC
        ORI 01H                     ; PIO1 PC0 = busy
        STA PIO1_PC
        MVI A,10H
        SIM                         ; SIM 10H: reset RST 7.5 latch
        LDA TICK_HOOK
        CPI 00H
        CNZ CALL_TICK_HOOK
        CALL REPORT_TASK
        CALL X_18C0
        CALL TICK_TASK
WAIT_SAMPLE_END:
        POP D
        POP PSW
        LDA PIO1_PC
        ANI 0FEH                    ; PIO1 PC0 = idle
        STA PIO1_PC
        JMP WAIT_SAMPLE

; WAIT_EPOCH: wait for a sample whose status (PIO2_PC bit 2, seen as bit 4 after RLC RLC) is set.
WAIT_EPOCH:
        CALL WAIT_SAMPLE
        MOV B,A
        ANI 10H                     ; bit 4 = PIO2_PC bit 2 (epoch flag)
        MOV A,B
        JZ WAIT_EPOCH
        LDA PIO1_PC
        ORI 01H
        STA PIO1_PC
        RET

; SHIFT_IN16: clock 8 bits out of the receiver shift register via PIO2_PB bit 4.
; PIO2_PC bit 4 -> B (phase-code stream), bit 3 -> C (second stream). Returns A = B.
SHIFT_IN16:
        MVI D,08H
        LDA PIO2_PC
        JMP SHIFT_IN_BIT
SHIFT_IN_CLK:
        MVI A,10H                   ; clock pulse on PIO2_PB bit 4
        CALL PULSE_PB
        LDA PIO2_PC
SHIFT_IN_BIT:
        RLC
        RLC
        RLC
        RLC
        PUSH PSW
        MOV A,B
        RAL
        MOV B,A
        POP PSW
        RLC
        MOV A,C
        RAL
        MOV C,A
        DCR D
        JNZ SHIFT_IN_CLK
        MOV A,B
        RET

; READ_PHASE: SHIFT_IN16 then XOR with PHASE_REF -> PHASE_CODE (2 bytes).
READ_PHASE:
        CALL SHIFT_IN16
        LXI H,PHASE_REF
        LXI D,PHASE_CODE
        XRA M
        STAX D
        MOV A,C
        XRA M
        INX D
        STAX D
        RET

; GET_SLOT_FLAGS: A = SLOT_FLAGS[SLOT_IDX].  GET_FLAGS_A: A = SLOT_FLAGS[A].
GET_SLOT_FLAGS:
        LDA SLOT_IDX
GET_FLAGS_A:
        LXI H,SLOT_FLAGS
        ADD L
        MOV L,A
        MOV A,M
        RET

; GET_SLOT_REC: HL -> 25-byte station record for SLOT_IDX.
; Slot 0 = REC_MASTER; otherwise REC_SEC + 25 * (flags & 3).
GET_SLOT_REC:
        LDA SLOT_IDX
        LXI H,REC_MASTER
        CPI 00H
        RZ
        CALL GET_FLAGS_A
SUB_04F7:
        LXI H,REC_SEC
        JMP REC_INDEX

; GET_SEC_TOA: HL -> REC_SEC_TOA + 25 * (A & 3).
GET_SEC_TOA:
        LXI H,REC_SEC_TOA
REC_INDEX:
        ANI 03H
        LXI D,0019H                 ; record stride 25
REC_INDEX_LOOP:
        DCR A
        RM
        DAD D
        JMP REC_INDEX_LOOP

; MUL9_INDEX: A = (HL + 9*A). Patched: the original x10 body survives at OLD_MUL10.
MUL9_INDEX:
        PUSH B
        MOV B,A
        RLC
        ADD B
        MOV B,A
        RLC
        ADD B
        JMP MUL9_INDEX_2

; OLD_MUL10: dead code left by an in-place patch (PUSH B / RLC / MOV C,A / RLC / RLC / ADD C).
OLD_MUL10:
        DB   0C5H,07H,4FH,07H,07H,81H
MUL9_INDEX_2:
        MOV C,A
        MVI B,00H
        DAD B
        MOV A,M
        POP B
        RET

; LOAD_CUR_REC: CUR_FLAGS = slot flags; copy the slot's 25-byte record into CUR_REC.
LOAD_CUR_REC:
        CALL GET_SLOT_FLAGS
        STA CUR_FLAGS
        CALL GET_SLOT_REC
        LXI B,CUR_REC
COPY25_TO_CUR:
        MVI E,19H
        JMP COPY_E                  ; copy 25 bytes

; OLD_LOAD_REC: dead code left by an in-place patch (copied in the opposite direction).
OLD_LOAD_REC:
        DB   0CDH,0E1H,04H,3AH,0BAH,6FH
        DB   77H,0CDH,0EBH,04H,44H,4DH
LOAD_REC_HL:
        LXI H,CUR_REC
        JMP COPY25_TO_CUR

; BIT_OF_STA: A = 1 << (A & 3), HL = TRACK_MASK.
BIT_OF_STA:
        LXI H,TRACK_MASK
        ANI 03H
        MOV B,A
        MVI A,01H
BIT_OF_LOOP:
        DCR B
        RM
        RLC
        JMP BIT_OF_LOOP

; COUNT_TRACKED: B = number of set bits in TRACK_MASK.
COUNT_TRACKED:
        MVI B,00H
        LDA TRACK_MASK
COUNT_TRK_LOOP:
        RRC
        RNC
        INR B
        JMP COUNT_TRK_LOOP

; SEC_TOA_TO_BIN / TOA_TO_BIN: A = bin(HL[1]) + (HL[2] >= 60H BCD ? 1 : 0).
SEC_TOA_TO_BIN:
        CALL GET_SEC_TOA
TOA_TO_BIN:
        MVI B,00H
        INX H
        INX H
        MOV A,M
        RAR
        SUI 30H                     ; '0'
        JM TOA_TO_BIN_2
        INR B
TOA_TO_BIN_2:
        DCX H
        MOV A,M
        PUSH B
        CALL BCD_TO_BIN
        POP B
        ADD B
        RET
BCD_INC_STORE:
        INR A
        JMP BIN_TO_DELTA

; RESET_PULSES: clear pulse list and reset CUR_PULSE_PTR to CUR_PULSES.
RESET_PULSES:
        CALL CLEAR_PULSES
        LXI H,CUR_PULSES
        SHLD CUR_PULSE_PTR
        RET

; CLEAR_PULSES: zero 17 bytes from CUR_NPULSE (falls into FILL_ZERO in the missing half).
CLEAR_PULSES:
        MVI B,11H
        LXI H,CUR_NPULSE
        JMP FILL_ZERO

; ORPHAN_058C: dead code from a patch, followed by the Loran-C phase-code table
; (CA F9 = master A / secondary A, 9F AC = master B / secondary B, each preceded by 21H LXI-skip).
ORPHAN_058C:
        DB   21H,04H,6FH,7EH,07H,3FH,1FH,77H
PHASE_CODE_TBL:
        DB   07H,21H,0CAH
        DB   0F9H,0D8H,21H
        DB   9FH,0ACH,0C9H

; PHASE_MISMATCH: B = popcount(PHASE_REF XOR B) = number of phase-code bit errors.
PHASE_MISMATCH:
        LDA PHASE_REF
        XRA B
        MVI C,08H
        MVI B,00H
PM_LOOP:
        RLC
        JNC PM_NEXT
        INR B
PM_NEXT:
        DCR C
        JNZ PM_LOOP
        RET

; FIRST_SAMPLE: wait one sample, SAMPLE_CNT = 8, read shift register, SAMPLE_LO = C.
FIRST_SAMPLE:
        CALL WAIT_SAMPLE
        MVI A,08H
        STA SAMPLE_CNT
        CALL SHIFT_IN16
        LXI H,SAMPLE_LO
        MOV M,C
        INX H
        MVI M,00H
        RET

; MATCH_PULSES: walk samples until WIN_END, matching the master phase code
; (0CAH on 'A' GRIs, 09FH on 'B' GRIs) and building the pulse-position list.
; Entry carry flag selects exact compare (CY=1) or 1-bit-tolerant compare (CY=0).
MATCH_PULSES:
        PUSH PSW
        LDA SAMPLE_LO
        LXI H,CUR_NPULSE
        MOV E,M
        JMP MP_TEST
MP_NEXT_SAMPLE:
        LXI H,SAMPLE_CNT
        INR M
        INX H
        RLC
        MOV A,M
        RAL
        MOV M,A
MP_TEST:
        MOV B,A
        MOV A,E
        CPI 00H
        JNZ MP_HAVE_PULSES
        POP PSW
        PUSH PSW
        JC MP_MASTER_A
        CALL PHASE_MISMATCH
        MOV A,B
        CPI 02H
        JC MP_ADD_PULSE
        JMP MP_CHK_END
MP_MASTER_A:
        MVI A,0CAH                  ; master phase code, GRI A
        XRA B
        JZ MP_ADD_PULSE
MP_CHK_END:
        LDA SAMPLE_CNT
        LXI H,WIN_END
        CMP M
        JZ MP_DONE_C
MP_WAIT:
        CALL WAIT_SAMPLE
        JMP MP_NEXT_SAMPLE
MP_DONE_C:
        POP PSW
        STC
        RET
MP_ADD_PULSE:
        LHLD CUR_PULSE_PTR
        LDA SAMPLE_CNT
        MOV M,A
        INX H
        SHLD CUR_PULSE_PTR
        LXI H,CUR_NPULSE
        INR M
        JMP MP_CHK_END
MP_HAVE_PULSES:
        POP PSW
        PUSH PSW
        JC MP_MASTER_B
        CALL PHASE_MISMATCH
        JMP MP_FIND
MP_MASTER_B:
        MVI A,9FH                   ; master phase code, GRI B
        XRA B
        MOV B,A
MP_FIND:
        LDA SAMPLE_CNT
        MOV C,A
        LXI H,CUR_PULSES
        MVI D,05H
MP_FIND_LOOP:
        MOV A,C
        CMP M
        JZ MP_FOUND
        INX H
        DCR D
        JNZ MP_FIND_LOOP
        JMP MP_CHK_END2
MP_FOUND:
        MOV A,B
        CPI 00H
        JZ MP_DONE_NC
        POP PSW
        PUSH PSW
        JC MP_CHK_END2
        MOV A,B
        CPI 02H
        JC MP_DONE_NC
MP_CHK_END2:
        LDA SAMPLE_CNT
        LXI H,WIN_END
        CMP M
        JZ MP_WINDOW_END
        JMP MP_WAIT
MP_WINDOW_END:
        CALL RESET_PULSES
        JMP MP_DONE_C
MP_DONE_NC:
        POP PSW
        XRA A
        RET

; SAMPLE_TO_BCD: BCD_DELTA_3 = BCD(SAMPLE_CNT - 9).  BIN_TO_DELTA: BCD_DELTA_3 = BCD(A).
SAMPLE_TO_BCD:
        LDA SAMPLE_CNT
        SUI 09H
BIN_TO_DELTA:
        CALL BIN_TO_BCD
        STA BCD_DELTA_3
        RET

; COUNT_BITS4: B = popcount of low 4 bits of A.
COUNT_BITS4:
        MVI C,04H
        MVI B,00H
CB4_LOOP:
        RRC
        JNC CB4_NEXT
        INR B
CB4_NEXT:
        DCR C
        JNZ CB4_LOOP
        RET

; CHK_NPULSE: carry if CUR_NPULSE bytes >= 6, else zero them.
CHK_NPULSE:
        LHLD CUR_NPULSE
        MOV A,L
        SUI 06H
        JP CHK_NPULSE_OK
        MOV A,H
        SUI 06H
        JP CHK_NPULSE_OK
        LXI H,RESET
        XRA A
        SHLD CUR_NPULSE
        RET
CHK_NPULSE_OK:
        STC
        RET

; ADJ_PULSES: pulse-position adjustment; computes a signed 16-bit offset (NEG_HL for
; negative) and adds/subtracts BCD_DELTA into BCD_ACC with BCD_ADD4 / BCD_SUB4.
ADJ_PULSES:
        LHLD CUR_PULSES_1
        LDA CUR_REC
        ANI 02H
        JZ ADJ_OFFSET
        LXI D,CUR_PULSES
        LDAX D
        MOV B,A
        RLC
        MOV A,B
        JNC ADJ_SUB16
        ADI 10H
        STAX D
        DCX H
        JMP ADJ_STORE
ADJ_SUB16:
        SUI 10H
        JM ADJ_OFFSET
        STAX D
        INX H
ADJ_STORE:
        SHLD CUR_PULSES_1
ADJ_OFFSET:
        XCHG
        LHLD CUR_PULSES_3
        DAD D
        MOV A,H
        RLC
        MVI E,00H
        CC NEG_HL
        PUSH H
        PUSH D
        MVI D,04H
ADJ_SHL4:
        MOV A,L
        RLC
        MOV L,A
        MOV A,H
        RAL
        MOV H,A
        DCR D
        JNZ ADJ_SHL4
        ADD E
        RLC
        CALL BIN_TO_BCD
        STA BCD_DELTA_3
        CPI 00H
        JZ ADJ_ZERO
        POP D
        POP H
        MVI H,00H
        MOV A,L
        ANI 0FH
        MOV L,A
        MOV A,E
        RRC
        PUSH PSW
        JNC ADJ_APPLY
        LXI D,0FFF0H                ; DE = -16
        DAD D
        CALL NEG_HL
ADJ_APPLY:
        SHLD CUR_PULSES_3
        LXI H,BCD_DELTA
        LXI B,BCD_ACC
        POP PSW
        JNC BCD_ADD4
        JMP BCD_SUB4
ADJ_ZERO:
        POP D
        POP H
        SHLD CUR_PULSES_3
        LDA CUR_FLAGS
        ANI 08H
        RZ
        LDA VAR_6FE2
        RRC
        RRC
        RNC
        LXI H,BCD_ACC_HI
        MVI M,02H
        RET

; NEG_HL: HL = -HL, E = E + 1 (sign flag).
NEG_HL:
        MOV A,H
        CMA
        MOV H,A
        MOV A,L
        CMA
        MOV L,A
        INX H
        INR E
        RET

; CALC_TD: form the time difference: copy TOA (or GRI) to BCD_ACC, adjust, store to CUR_TOA.
CALC_TD:
        LDA CUR_FLAGS
        ANI 08H
        JNZ CALC_TD_GRI
        LDA SLOT_IDX
        CPI 00H
        JZ CALC_TD_TMP
        LXI H,CUR_TOA
        LXI B,BCD_ACC
        CALL COPY4
        LHLD CUR_PULSES_1
        LXI B,0001H                 ; BC = 1
        CALL X_0B8D
        SHLD CUR_PULSES_1
        CALL ADJ_PULSES
        LXI H,BCD_ACC
        JMP CALC_TD_STORE
CALC_TD_GRI:
        LXI H,GRI_BCD
        LXI B,BCD_ACC
        CALL COPY4
        CALL ADJ_PULSES
        LXI H,BCD_ACC
        LXI B,GRI_TMP
        CALL COPY4
        LDA SLOT_IDX
        CPI 00H
        JNZ CALC_TD_EXIT
CALC_TD_TMP:
        LXI H,GRI_TMP
CALC_TD_STORE:
        LXI B,CUR_TOA
        CALL COPY4
CALC_TD_EXIT:
        LXI H,VAR_6FE3
        RET

; BCD_ADD4: (BC) += (HL), 4 packed-BCD bytes, LS byte first.
; PTR_TO_MSB: HL += DE-1, BC += DE-1 (point both at the MS byte).
BCD_ADD4:
        LXI D,0004H                 ; DE = 4 bytes
        CALL PTR_TO_MSB
        XRA A
BCD_ADD4_LOOP:
        LDAX B
        ADC M
        DAA
        STAX B
        DCR E
        RZ
        DCX B
        DCX H
        JMP BCD_ADD4_LOOP
PTR_TO_MSB:
        DAD D
        DCX H
        PUSH H
        MOV H,B
        MOV L,C
        DAD D
        DCX H
        MOV B,H
        MOV C,L
        POP H
        RET

; BCD_SUB4: (BC) -= (HL), 4 packed-BCD bytes, ten's-complement subtract.
BCD_SUB4:
        LXI D,0004H                 ; DE = 4 bytes
        CALL PTR_TO_MSB
        PUSH D
        PUSH B
        POP D
        POP B
        STC
BCD_SUB4_LOOP:
        MVI A,99H
        ACI 00H
        SUB M
        XCHG
        ADD M
        DAA
        MOV M,A
        XCHG
        DCR C
        RZ
        DCX D
        DCX H
        JMP BCD_SUB4_LOOP

; COPY4: copy 4 bytes (HL) -> (BC).  COPY_E: copy E bytes.
COPY4:
        MVI E,04H
COPY_E:
        MOV A,M
        STAX B
        INX H
        INX B
        DCR E
        JNZ COPY_E
        RET

; MUL8: BC = C * D (shift-add, 8x8 -> 16).
MUL8:
        MVI B,00H
        MVI E,09H
MUL8_LOOP:
        MOV A,C
        RAR
        MOV C,A
        DCR E
        RZ
        MOV A,B
        JNC MUL8_SHIFT
        ADD D
MUL8_SHIFT:
        RAR
        MOV B,A
        JMP MUL8_LOOP

; BCD_TO_BIN: A = binary value of packed-BCD byte A (uses HI_NIBBLE in the missing half).
BCD_TO_BIN:
        MOV B,A
        CALL HI_NIBBLE
        MOV E,A
        XRA A
        MVI D,0AH
B2B_LOOP:
        DCR E
        JM B2B_DONE
        ADD D
        JMP B2B_LOOP
