        ANI 0C0H
        CPI 80H
        RNZ
        MVI M,00H
        RET
X_0F08:
        LDA TRACK_STATE
        CPI 01H
        RNZ
        LDA ACQ_COUNT
        CPI 04H
        RP
        LDA SLOT_RESULT
        CPI 00H
        RZ
        MOV D,A
        PUSH D
        CALL GET_FLAGS_A
        POP D
        RLC
        RC
        MOV A,D
X_0F23:
        STA SLOT_IDX_B
        CALL GET_FLAGS_A
        MVI M,80H
        MVI A,20H                   ; ' '
        STA TRACK_STATE
        RET
X_0F31:
        LDA SLOT_FLAGS
        MOV B,A
        LXI H,RAM1_BASE
        MOV A,M
        CPI 00H
        PUSH H
        JNZ L_0F5C
        LDA FIRST_SLOT
        CALL GET_FLAGS_A
        ANI 60H                     ; '`'
        CPI 60H                     ; '`'
        XCHG
        POP H
        RNZ
        MVI M,01H
        LXI H,REC_MASTER
        CALL X_0FE9
L_0F54:
        LDA FIRST_SLOT
        MOV B,A
        XRA A
        JMP L_0F6F
L_0F5C:
        CPI 01H
        POP H
        JNZ L_0F9E
        MOV A,B
        ANI 10H
        JZ L_0FBC
        MVI M,02H
X_0F6A:
        MVI B,00H
        LDA FIRST_SLOT
L_0F6F:
        PUSH B
        PUSH PSW
        CALL GET_FLAGS_A
        MOV A,M
        ANI 0F7H
        MOV M,A
        POP PSW
        CPI 00H
        LXI H,M_6F2D
        LXI D,M_6F46
        JZ L_0F85
        XCHG
L_0F85:
        POP B
        PUSH D
        PUSH H
        MOV A,B
        CALL GET_FLAGS_A
        MOV A,M
        ORI 08H
        MOV M,A
        POP H
        POP B
        PUSH H
        MVI E,05H
        CALL COPY_E
        POP H
        MVI B,05H
        JMP FILL_ZERO
L_0F9E:
        MOV A,B
        LHLD M_6F36
        LXI D,M_FF9C
        DAD D
        ANI 08H
        JZ CHK_H_NEG
        MOV A,H
        RLC
        JC L_0FBC
        LDA FIRST_SLOT
        CALL GET_FLAGS_A
        RLC
        RLC
        JC L_0F54
        RET
L_0FBC:
        MVI A,01H
X_0FBE:
        PUSH PSW
        CALL GET_FLAGS_A
        MOV B,A
        RLC
        RLC
        JNC L_1018
        RLC
        RLC
        JC L_1018
        MOV A,B
        CALL SUB_04F7
        MOV A,M
        ANI 80H
        JNZ L_1018
        POP PSW
        MOV B,A
        LDA FIRST_SLOT
        CMP B
        JNZ L_0FF7
        LDA RAM1_BASE
        CPI 02H
        MOV A,B
        JNZ SLOT_INC_CHK
X_0FE9:
        MOV A,M
        ORI 82H
        MOV M,A
        LXI D,BCD_K_00000110
        DAD D
        MVI M,00H
        DCX H
        MVI M,00H
        RET
L_0FF7:
        PUSH PSW
        PUSH H
        PUSH B
        MOV A,B
        RLC
        MOV C,A
        RLC
        RLC
        ADD C

; SLOTTBL_CHK: tail of a routine from the missing half (entered from 0FFxH):
; test SLOT_TBL[A]; clean up stack and continue at X_0FE9 or SLOT_INC_CHK.
SLOTTBL_CHK:
        MOV C,A
        MVI B,00H
D_1004       EQU  $+1
        LXI H,SLOT_TBL
        DAD B
        MOV A,M
        CPI 00H
        POP B
        POP H
        JZ SLOTTBL_ZERO
        POP PSW
        JMP X_0FE9
SLOTTBL_ZERO:
        POP PSW
        MOV A,B
        JMP SLOT_INC_CHK
L_1018:
        DB   0F1H
SLOT_INC_CHK:
        INR A
        LXI H,SLOT_COUNT
        CMP M
        JNZ X_0FBE
        RET
CHK_H_NEG:
        MOV A,H
        RLC
        JC X_0F6A
        RET

; SLOTREC_PHASE: update the 9-byte per-slot record from PHASE_CODE_HI.
SLOTREC_PHASE:
        LDA SLOT_IDX
        LXI H,SLOTREC_5
        CALL MUL9_INDEX
        MOV C,M
        LDA PHASE_CODE_HI
        XRI 3FH                     ; '?'
        DCR C
        DCR C
        DCR C
        MVI E,03H
SRP_LOOP:
        RLC
        JNC SRP_NEXT
        INR C
        INR C
SRP_NEXT:
        DCR E
        JNZ SRP_LOOP
        MOV A,C
        ADI 08H
        RLC
        MVI A,00H
        RAR
        INX H
        MOV M,A
        DCX H
        MOV A,C
        RLC
        JNC SRP_STORE
        MOV A,C
        ADI 10H
        RLC
        RNC
SRP_STORE:
        MOV M,C
        RET

; SLOTREC_UPDATE: bump the per-slot counter, subtract BCD_TMP / 0400H, add popcount, etc.
SLOTREC_UPDATE:
        LDA SLOT_IDX
        LXI H,SLOTREC_CNT
        CALL MUL9_INDEX
        INX H
        PUSH H
        DCX H
        INR M
        MOV A,M
        CPI 02H
        JZ SRU_SUB
        CPI 05H
        JNZ SRU_SUB4
        MVI M,00H
SRU_SUB:
        POP H
        PUSH H
        LXI B,M_6FEA
        CALL COPY4
        LXI H,BCD_TMP
        MVI M,00H
        POP B
        PUSH B
        LXI H,BCD_TMP
        CALL BCD_SUB4
SRU_SUB4:
        LXI B,0400H                 ; B = 4 bytes (C ignored)
        LXI H,BCD_TMP
        CALL FILL_ZERO
        LXI H,BCD_TMP_2
        MVI M,04H
        POP B
        PUSH B
        LXI H,BCD_TMP
        CALL BCD_SUB4
        LXI H,BCD_TMP_2
        MVI M,00H
        LDA PHASE_CODE_HI
        CMA
        MVI E,08H
SRU_CNT_LOOP:
        RRC
        JNC SRU_CNT_NEXT
        INR M
SRU_CNT_NEXT:
        DCR E
        JNZ SRU_CNT_LOOP
        POP B
        PUSH B
        LXI H,BCD_TMP
        CALL BCD_ADD4
        POP B
        LDAX B
        CPI 00H
        JZ SRU_ZERO
        MOV H,B
        MOV L,C
        PUSH B
        MVI B,04H
        CALL FILL_ZERO
        POP B
        RET
SRU_ZERO:
        INX B
        LDAX B
        ANI 0F0H
        RZ
        MVI A,10H
        STAX B
        INX B
        MVI A,00H
        STAX B
        RET

; CALL_TICK_HOOK: jump through TICK_HOOK (set by the missing half or the monitor).
CALL_TICK_HOOK:
        LHLD TICK_HOOK
        PCHL

; SERIAL_POLL: 8251 receive state machine (RX_STATE / PROTO_STATE). See docs/serial-protocol.md.
; Also runs PLOT_OUT when OUT_MODE = 2.
SERIAL_POLL:
        LDA OUT_MODE
        CPI 02H
        CZ PLOT_OUT
        LDA RX_STATE
        CPI 00H
        JNZ RX_STATE_N
        LDA USART_CTRL
        RAR                         ; RxRDY?
        RAR
        RNC
        LDA USART_DATA
        STA RX_CHAR
        LDA RX_STATE
        INR A
        STA RX_STATE
        JMP SERIAL_POLL
RX_STATE_N:
        LDA USART_CTRL
        RAR                         ; TxRDY?
        RNC
        LDA PIO1_PC
        ORI 01H
        STA PIO1_PC
        LDA RX_STATE
        INR A
        STA RX_STATE
        CPI 02H
        JNZ TX_STATE_N
        LDA RX_CHAR
        CPI 12H                     ; DC2: reset protocol
        JNZ RX_CMD_14
        MVI A,00H
        STA PROTO_STATE
        STA OUT_MODE
        JMP RX_DONE
RX_CMD_14:
        CPI 14H                     ; DC4: OUT_MODE = 1
        JNZ RX_CMD_07
        MVI A,01H
        STA OUT_MODE
        JMP RX_DONE
RX_CMD_07:
        CPI 07H                     ; BEL: reset print buffer, PROTO_STATE = 1
        JNZ RX_CMD_05
        LXI H,PRTBUF
        SHLD PRTBUF_PTR
        MVI A,00H
        STA OUT_MODE
        MVI A,01H
        STA PROTO_STATE
        JMP RX_DONE
RX_CMD_05:
        CPI 05H                     ; ENQ: PROTO_STATE = 2
        JNZ RX_PROTO_4
        MVI A,02H
        STA PROTO_STATE
        JMP RX_DONE
RX_PROTO_4:
        LDA PROTO_STATE
        CPI 04H
        JNZ RX_PROTO_5
        LDA RX_CHAR
        CPI 41H                     ; 'A'
        JNZ RX_PROTO_4B
        MVI A,05H
        STA PROTO_STATE
        JMP RX_DONE
RX_PROTO_4B:
        CPI 2CH                     ; ','
        JNZ RX_PROTO_RESET
        MVI A,06H
        STA PROTO_STATE
        JMP RX_DONE
RX_PROTO_RESET:
        MVI A,00H
        STA PROTO_STATE
        JMP RX_DONE
RX_PROTO_5:
        LDA PROTO_STATE
        CPI 05H
        JNZ RX_PROTO_6
        LDA RX_CHAR
        LXI H,UNIT_ID
        CMP M
        JNZ RX_PROTO_SET1
        MVI A,02H
        STA PROTO_STATE
        JMP RX_DONE
RX_PROTO_SET1:
        MVI A,01H
        STA PROTO_STATE
        JMP RX_DONE
RX_PROTO_6:
        LDA PROTO_STATE
        CPI 06H
        JNZ RX_CHK_ESC
        LDA RX_CHAR
        LXI H,UNIT_ID
        CMP M
        JNZ RX_PROTO_SET1
        MVI A,03H
        STA PROTO_STATE
        JMP RX_DONE
RX_CHK_ESC:
        LDA RX_CHAR
        CPI 1BH                     ; ESC: PROTO_STATE = 4
        JNZ RX_CHK_MON
        MVI A,04H
        STA PROTO_STATE
        JMP RX_DONE
RX_CHK_MON:
        LDA PROTO_STATE
        CPI 03H
        JZ MON_CMD
RX_DONE:
        MVI A,00H
        STA RX_STATE
        RET

; MON_CMD: memory monitor commands, active when PROTO_STATE = 3. Char is echoed first.
;   ' ' deposit MON_WORD low byte at (MON_PTR), advance   R back up one address
;   S set MON_PTR = MON_WORD   G call MON_WORD   M dump memory   K/P/O output mode 1/2/0
;   0-9 A-F shift hex digit into MON_WORD
MON_CMD:
        LDA RX_CHAR
        STA USART_DATA              ; echo command char
        CPI 20H                     ; ' '
        JNZ MON_CMD_R
        LDA MON_DIGIT_FLAG
        CPI 00H
        LHLD MON_PTR
        JZ MON_ADVANCE
        LDA MON_WORD
        MOV M,A
MON_ADVANCE:
        INX H
        SHLD MON_PTR
MON_CLR_DIGIT:
        MVI A,00H
        STA MON_DIGIT_FLAG
        JMP SERIAL_POLL
MON_CMD_R:
        CPI 52H                     ; 'R'
        JNZ MON_CMD_S
        LHLD MON_PTR
        DCX H
        SHLD MON_PTR
        JMP MON_CLR_DIGIT
MON_CMD_S:
        CPI 53H                     ; 'S'
        JNZ MON_CMD_G
        LHLD MON_WORD
        SHLD MON_PTR
        JMP MON_CLR_DIGIT
MON_CMD_G:
        CPI 47H                     ; 'G'
        JNZ MON_CMD_K
        CALL MON_GO
        JMP MON_CLR_DIGIT
MON_GO:
        LHLD MON_WORD
        PCHL
MON_CMD_K:
        CPI 4BH                     ; 'K'
        JNZ MON_CMD_P
        MVI A,01H
        STA OUT_MODE
        JMP SERIAL_POLL
MON_CMD_P:
        CPI 50H                     ; 'P'
        JNZ MON_CMD_M
        MVI A,02H
        STA OUT_MODE
        JMP SERIAL_POLL
MON_CMD_M:
        CPI 4DH                     ; 'M'
        JNZ MON_CMD_O
        MVI A,0CH
        STA RX_STATE
        JMP SERIAL_POLL
MON_CMD_O:
        CPI 4FH                     ; 'O'
        JNZ MON_HEX_DIGIT
        MVI A,00H
        STA OUT_MODE
        JMP SERIAL_POLL
MON_HEX_DIGIT:
        CPI 3AH                     ; ':'
        JM MON_HEX_SHIFT
        ADI 09H
MON_HEX_SHIFT:
        ANI 0FH
        LHLD MON_WORD
        DAD H
        DAD H
        DAD H
        DAD H
        ORA L
        MOV L,A
        SHLD MON_WORD
        MVI A,00H
        STA RX_STATE
        MVI A,01H
        STA MON_DIGIT_FLAG
        JMP SERIAL_POLL
TX_STATE_N:
        CPI 03H
        JZ TX_CR                    ; state 3: send CR
        CPI 04H
        JZ TX_LF                    ; state 4: send LF
        CPI 05H
        JZ TX_PTR_HI
        CPI 06H
        JZ TX_ECHO                  ; state 6/8/B: echo char
        CPI 07H
        JZ TX_PTR_LO
        CPI 08H
        JZ TX_ECHO
        CPI 09H
        JZ TX_SPACE                 ; state 9: send space
        CPI 0AH
        JZ TX_MEM_BYTE
        CPI 0BH
        JZ TX_ECHO
        CPI 0CH
        JNZ TX_WAIT_TXRDY
        XRA A
        STA MON_WORD
        STA MON_WORD_HI
        STA RX_STATE

; TX_DASH: send '-'. The three LXI H instructions are 21H skip-prefixes over
; MVI A,' ' / MVI A,0DH / MVI A,0AH so that entries at 12D1/12D4/12D7 send those chars.
TX_DASH:
        MVI A,2DH                   ; '-'
TX_SPACE     EQU  $+1
        LXI H,203EH                 ; 21H skip prefix: MVI A,' ' at 12D1
TX_CR        EQU  $+1
        LXI H,0D3EH                 ; 21H skip prefix: MVI A,0DH at 12D4
TX_LF        EQU  $+1
        LXI H,0A3EH                 ; 21H skip prefix: MVI A,0AH at 12D7
        STA USART_DATA
        JMP SERIAL_POLL
TX_WAIT_TXRDY:
        LDA USART_CTRL
        RAR
        RAR
        JNC TX_DUMP_STATE
        XRA A
        STA RX_STATE
        JMP SERIAL_POLL
TX_DUMP_STATE:
        LDA RX_STATE
        CPI 0DH
        JZ TX_DUMP_BYTE
        CPI 0EH
        JZ TX_ECHO
        MVI A,0CH
        STA RX_STATE
        JMP TX_DASH
TX_DUMP_BYTE:
        LHLD MON_WORD
        LDA MON_LAST
        CMP M
        JZ TX_DUMP_SAME
        MOV A,M
        STA MON_LAST
        JMP TX_HEX_BYTE
TX_DUMP_SAME:
        MVI A,0CH
        STA RX_STATE
        RET
TX_ECHO:
        LDA RX_CHAR
        STA USART_DATA
        JMP SERIAL_POLL
TX_PTR_LO:
        LDA MON_PTR
        JMP TX_HEX_BYTE
TX_PTR_HI:
        LDA MON_PTR_HI
TX_HEX_BYTE:
        PUSH PSW
        RAR
        RAR
        RAR
        RAR
        ANI 0FH
        CPI 0AH
        JM TX_HEX_HI
        ADI 07H
TX_HEX_HI:
        ADI 30H                     ; '0'
        STA USART_DATA
        POP PSW
        ANI 0FH
        CPI 0AH
        JM TX_HEX_LO
        ADI 07H
TX_HEX_LO:
        ADI 30H                     ; '0'
        STA RX_CHAR
        JMP SERIAL_POLL
TX_MEM_BYTE:
        LHLD MON_PTR
        MOV A,M
        JMP TX_HEX_BYTE

; PLOT_OUT: strip-chart output mode. Emits CR, LF then 80 columns with ' ' / '!' / '"' / '#'
; marking the two values from PLOT_VALUES.
PLOT_OUT:
        LDA USART_CTRL
        RRC
        RNC
        LDA PIO1_PC
        ORA C
        STA PIO1_PC
        LDA PLOT_COL
        CPI 50H                     ; 'P'
        MVI D,0DH
        JZ PLOT_SEND
        LDA PLOT_COL
        CPI 51H                     ; 'Q'
        JNZ PLOT_COLUMN
        MVI A,00H
        STA PLOT_COL
        CALL PLOT_VALUES
        MOV H,B
        MOV L,C
        SHLD PLOT_BASE
        MVI D,0AH
        JMP PLOT_SEND
PLOT_COLUMN:
        LHLD PLOT_BASE
        MOV B,H
        MOV C,L
        MVI D,20H                   ; ' '
        LDA PLOT_COL
        CMP B
        JNZ PLOT_CHK_C
        MOV A,D
        ORI 01H
        MOV D,A
PLOT_CHK_C:
        CMP C
        JNZ PLOT_SEND
        MOV A,D
        ORI 02H
        MOV D,A
PLOT_SEND:
        LXI H,PLOT_COL
        INR M
        MOV A,D
        STA USART_DATA
        RET
PLOT_VALUES:
        LDA SEL_A
        LXI H,REC_MASTER_14
        CPI 0AH
        JNC PV_SCALE
        LXI H,SLOT_FLAGS
        ADD L
        MOV L,A
        MOV A,M
        LXI H,REC_SEC_14
PV_INDEX:
        ANI 03H
        LXI D,0019H                 ; record stride 25
        DCR A
        JM PV_SCALE
        DAD D
        JMP PV_INDEX
PV_SCALE:
        MOV A,M
        RRC
        RRC
        ADI 08H
        ANI 3FH                     ; '?'
        INR A
        INR A
        INR A
        MOV B,A
        INX H
        INX H
        INX H
        MOV A,M
        CMA
        RRC
        RRC
        ADI 08H
        ANI 3FH                     ; '?'
        INR A
        INR A
        INR A
        MOV C,A
        RET

; DISP_REFRESH: write the 8279 display RAM (cmd 90H = write, auto-inc, addr 0).
; 7 bytes: 3 pairs interleaving high nibbles of 7034..7036 with 7037..7039, then 703A.
; Never reached from the dumped halves; called from the missing half.
DISP_REFRESH:
        MVI A,90H
        STA KDC_CMD
        LXI B,M_7037
        LXI H,M_7034
        MVI E,03H
DISP_LOOP:
        MOV A,M
        ANI 0F0H
        MOV D,A
        LDAX B
        RRC
        RRC
        RRC
        RRC
        ANI 0FH
        ORA D
        STA KDC_DATA
        MOV A,M
        RLC
        RLC
        RLC
        RLC
        ANI 0F0H
        MOV D,A
        LDAX B
        ANI 0FH
        ORA D
        STA KDC_DATA
        INX H
        INX B
        DCR E
        JNZ DISP_LOOP
        LDA M_703A
        STA KDC_DATA
        RET

; READ_SWITCHES: read the 6 thumbwheel rows via the 8279 sensor RAM (cmd 50H).
; Rows 0,1 -> SEL_A/SEL_B (digit+1, must be 1..9); rows 2..5 -> GRI (first digit >= 4).
; Invalid settings call the X_199x error handlers in the missing half and retry.
READ_SWITCHES:
        MVI A,0E0H
        STA KDC_CMD                 ; 8279: end interrupt
        MVI A,50H                   ; 'P'
        STA KDC_CMD                 ; 8279: read sensor RAM row 0, auto-inc
        LDA KDC_DATA
        CALL SW_TO_DIGIT
        INR A
        CPI 0AH
        JC RSW_SELB
        CALL X_1990
        JMP READ_SWITCHES
RSW_SELB:
        STA SEL_A
        LDA KDC_DATA
        CALL SW_TO_DIGIT
        INR A
        CPI 0AH
        JC RSW_GRI1
        CALL X_1995
        JMP READ_SWITCHES
RSW_GRI1:
        STA SEL_B
        LDA KDC_DATA
        CALL SW_TO_DIGIT
        JC RSW_GRI1_CHK
        CALL X_199A
        JMP READ_SWITCHES
RSW_GRI1_CHK:
        CPI 04H
        JNC RSW_GRI2                ; GRI first digit must be 4..9
        CALL X_199A
        JMP READ_SWITCHES
RSW_GRI2:
        RLC
        RLC
        RLC
        RLC
        MOV L,A
        LDA KDC_DATA
        CALL SW_TO_DIGIT
        JC RSW_GRI3
        CALL X_199F
        JMP READ_SWITCHES
RSW_GRI3:
        ORA L
        MOV L,A
        LDA KDC_DATA
        CALL SW_TO_DIGIT
        JC RSW_GRI4
        CALL X_19A4
        JMP READ_SWITCHES
RSW_GRI4:
        RLC
        RLC
        RLC
        RLC
        MOV H,A
        LDA KDC_DATA
        CALL SW_TO_DIGIT
        JC RSW_STORE_GRI
        CPI 0BH
        JZ RSW_GRI4_BLANK
        CALL X_19A9
        JMP READ_SWITCHES
RSW_GRI4_BLANK:
        MVI A,00H
RSW_STORE_GRI:
        ORA H
        MOV H,A
        SHLD GRI_SW
        JMP SCAN_SWITCHES

; SW_TO_DIGIT: convert a sensor row byte to a digit. Rows are 9's-complement BCD on bits 0..5:
; digit = 9 - (row & 3FH), valid (carry set) when row & 3FH <= 9. Otherwise returns
; 0BH for the blank position (carry clear).
SW_TO_DIGIT:
        ANI 3FH                     ; '?'
        XRI 0FFH
        ADI 0AH
        CPI 0AH
        RC
        RRC
        RRC
        RRC
        RRC
        ADI 0CH
        ANI 0FH
        STC
        CMC
        RET

; TICK_TASK: run once per RST 7.5 tick. TICK_BCD += 2 (BCD); every 20 ticks call X_19E7.
; If RST 5.5 (8279 IRQ) is pending: send End-Interrupt (0E0H) and set KEY_CHANGED;
; on a later tick with KEY_CHANGED set, rescan the switches.
TICK_TASK:
        LDA TICK_BCD
        INR A
        INR A
        XRI 00H
        DAA
        STA TICK_BCD
        ANI 3FH                     ; '?'
        CZ X_19E7
        RIM
        ANI 10H
        JZ TICK_CHK_KEYS
        MVI A,0E0H
        STA KDC_CMD                 ; 8279: end interrupt (clear IRQ)
        MVI A,01H
        STA KEY_CHANGED
        RET
TICK_CHK_KEYS:
        LDA KEY_CHANGED
        CPI 00H
        RZ

; SCAN_SWITCHES: read sensor rows 0..5 and 6..7. Row 0/1 -> SEL_A/SEL_B, rows 2..5 -> SW_D1..4,
; rows 6/7 bit 7/6 -> BTN_STATE / BUTTONS (push-button edges).
; SEL_B = 0CH (blank) enters set-up: SW_D1..4 latched to SW_HI/SW_LO; SW_D1 = blank selects
; a configuration item by SW_D2: 0-3 baud (110/300/1200/19200), 4-9 OPTIONS bits.
SCAN_SWITCHES:
        MVI A,50H                   ; 'P'
        STA KDC_CMD                 ; 8279: read sensor RAM row 0, auto-inc
        LDA KDC_DATA
        CALL SW_TO_DIGIT
        INR A
        STA SEL_A
        LDA KDC_DATA
        CALL SW_TO_DIGIT
        INR A
        STA SEL_B
        LDA KDC_DATA
        CALL SW_TO_DIGIT
        STA SW_D1
        LDA KDC_DATA
        CALL SW_TO_DIGIT
        STA SW_D2
        LDA KDC_DATA
        CALL SW_TO_DIGIT
        STA SW_D3
        LDA KDC_DATA
        CALL SW_TO_DIGIT
        STA SW_D4
        MVI A,00H
        STA KEY_CHANGED
        MVI A,56H                   ; 'V'
        STA KDC_CMD                 ; 8279: read sensor RAM row 6, auto-inc
        LDA KDC_DATA
        MOV B,A
        ANI 80H
        JZ SCAN_BTN_ROW7
        LDA BTN_STATE
        XRI 80H
        STA BTN_STATE
SCAN_BTN_ROW7:
        MOV A,B
        ANI 40H                     ; '@'
        RLC
        MOV B,A
        LDA KDC_DATA
        MOV C,A
        ANI 80H
        JZ SCAN_BTN_CLR
        LDA BTN_STATE
        ORI 40H                     ; '@'
        JMP SCAN_BTN_STORE
SCAN_BTN_CLR:
        LDA BTN_STATE
        ANI 0BFH
SCAN_BTN_STORE:
        STA BTN_STATE
        MOV A,C
        ANI 40H                     ; '@'
        ORA B
        STA BUTTONS
        LDA SEL_B
        CPI 0CH                     ; SEL_B blank -> set-up mode
        JNZ SCAN_NORMAL
        LDA BTN_STATE
        MOV B,A
        ANI 40H                     ; '@'
        STA BTN_STATE
        MOV A,B
        RLC
        JNC SCAN_BTN_EDGES
        LDA SW_LATCHED
        CPI 00H
        JNZ SCAN_CLR_STATS
        LDA SW_D1
        RLC
        RLC
        RLC
        RLC
        ANI 0F0H
        MOV B,A
        LDA SW_D2
        ANI 0FH
        ORA B
        STA SW_HI
        LDA SW_D3
        RLC
        RLC
        RLC
        RLC
        ANI 0F0H
        MOV B,A
        LDA SW_D4
        ANI 0FH
        ORA B
        STA SW_LO
        MVI A,00H
        STA VAR_704F
        MVI A,01H
        STA SW_LATCHED
        JMP SCAN_BTN_EDGES
SCAN_CLR_STATS:
        MVI A,00H
        STA VAR_70BD
        STA VAR_70BE
        STA VAR_7050
        STA VAR_7051
SCAN_BTN_EDGES:
        LDA BUTTONS
        MOV B,A
        MVI A,00H
        STA BUTTONS
        MOV A,B
        RLC
        JNC SCAN_BTN_EDGE2
        LDA STATUS_BITS
        ORI 80H
        STA STATUS_BITS
SCAN_BTN_EDGE2:
        MOV A,B
        RLC
        RLC
        JNC SCAN_DONE
        LDA STATUS_BITS
        ANI 7FH
        STA STATUS_BITS
SCAN_DONE:
        RET
SCAN_NORMAL:
        LDA BUTTONS
        CPI 00H
        RZ
        LDA SEL_B
        CPI 0BH
        RZ
        MVI A,02H
        STA RESTART_REQ
        LDA BUTTONS
        ANI 40H                     ; '@'
        RZ
        LDA SW_D1
        CPI 0BH                     ; SW_D1 blank -> configuration item
        JNZ SCAN_SEL_CHK
        LDA SW_D3
        RLC
        RLC
        RLC
        RLC
        ANI 0F0H
        MOV B,A
        LDA SW_D4
        ORA B
        STA UNIT_ID
        LDA SW_D2
        CPI 00H
        JNZ CFG_BAUD_1
        LXI H,458AH                 ; timer 058AH (1418): 110 baud
        SHLD PIO2_TMRLO
        MVI A,0C3H
        STA PIO2_CMD
        JMP SCAN_SEL_CHK
CFG_BAUD_1:
        CPI 01H
        JNZ CFG_BAUD_2
        LXI H,4208H                 ; timer 0208H (520): 300 baud
        SHLD PIO2_TMRLO
        MVI A,0C3H
        STA PIO2_CMD
        JMP SCAN_SEL_CHK
CFG_BAUD_2:
        CPI 02H
        JNZ CFG_BAUD_3
        LXI H,4082H                 ; timer 0082H (130): 1200 baud
        SHLD PIO2_TMRLO
        MVI A,0C3H
        STA PIO2_CMD
        JMP SCAN_SEL_CHK
CFG_BAUD_3:
        CPI 03H
        JNZ CFG_OPT_4
        LXI H,4008H                 ; timer 0008H (8): 19200 baud
        SHLD PIO2_TMRLO
        MVI A,0C3H
        STA PIO2_CMD
        JMP SCAN_SEL_CHK
CFG_OPT_4:
        CPI 04H
        JNZ CFG_OPT_5
        MVI A,00H
        STA OPTIONS
        JMP SCAN_SEL_CHK
CFG_OPT_5:
        CPI 05H
        JNZ CFG_OPT_6
        MVI A,81H
        STA OPTIONS
        JMP SCAN_SEL_CHK
CFG_OPT_6:
        CPI 06H
        JNZ CFG_OPT_7
        MVI A,82H
        STA OPTIONS
        JMP SCAN_SEL_CHK
CFG_OPT_7:
        CPI 07H
        JNZ CFG_OPT_8
        MVI A,84H
        STA OPTIONS
        JMP SCAN_SEL_CHK
CFG_OPT_8:
        CPI 08H
        JNZ CFG_OPT_9
        MVI A,88H
        STA OPTIONS
        JMP SCAN_SEL_CHK
CFG_OPT_9:
        CPI 09H
        JNZ SCAN_SEL_CHK
        MVI A,80H
        STA OPTIONS
SCAN_SEL_CHK:
        LDA SEL_A
        LXI H,SLOT_COUNT
        CMP M
        RP
        CALL X_1DBD
        JC SCAN_SEL_STORE
        LDA SLOT_IDX_B
        CALL GET_FLAGS_A
        ANI 0C0H
        CPI 80H
        RZ
        CALL X_1E05
SCAN_SEL_STORE:
        STA SLOT_RESULT
        MVI A,01H
        STA NEW_DATA
        RET

; TX_SERVICE: when OUT_MODE = 0 and 8251 TxRDY, send next char from PRTBUF.
TX_SERVICE:
        LDA OUT_MODE
        CPI 00H
        RNZ
        LDA USART_CTRL
        RRC
        RNC
        LDA TX_PENDING
        RRC
        RC
        LDA PIO1_PC
        ORI 01H
        STA PIO1_PC
        CALL PRTBUF_GET
        JNC TX_SEND
        MVI A,01H
        STA TX_PENDING
        RET
TX_SEND:
        STA USART_DATA
        RET

; PRTBUF_GET: pull next char from the print buffer (PRTBUF_PTR walks down to PRTBUF).
PRTBUF_GET:
        LHLD PRTBUF_PTR
        LXI D,PRTBUF
        MOV A,D
        CMP H
        JNZ PRTBUF_POP
        MOV A,E
        CMP L
        JNZ PRTBUF_POP
        MOV A,M
        STC
        RET
PRTBUF_POP:
        STC
        CMC
        DCX H
        MOV A,M
        SHLD PRTBUF_PTR
        RET

; REPORT_TASK: sequence the periodic data report over the serial port (RPT_STATE 0..8,
; 0FEH = idle, 0FFH = armed). Items are formatted by X_189B / X_1878 in the missing half.
REPORT_TASK:
        LDA RPT_STATE
        CPI 0FEH
        JNZ RPT_RUNNING
        LDA PROTO_STATE
        CPI 00H
        JZ RPT_CHK_IDLE
        CPI 02H
        RNZ
        MVI A,01H
        STA PROTO_STATE
        JMP RPT_ARM
RPT_CHK_IDLE:
        LDA TICK_BCD
        CPI 00H
        RNZ
        LDA OPTIONS
        RLC
        JNC RPT_ARM
        LDA VAR_704F
        ANI 0FH
        CPI 00H
        RNZ
        LDA OPTIONS
        RRC
        JC RPT_ARM
        LDA VAR_704F
        CPI 00H
        RNZ
        LDA OPTIONS
        RRC
        RRC
        JC RPT_ARM
        LDA SW_LO
        ANI 0FH
        CPI 00H
        RNZ
        LDA OPTIONS
        RRC
        RRC
        RRC
        JC RPT_ARM
        LDA SW_LO
        CPI 00H
        RNZ
        LDA OPTIONS
        RRC
        RRC
        RRC
        RRC
        JC RPT_ARM
        LDA SW_HI
        CPI 00H
        RNZ
RPT_ARM:
        MVI A,0FFH
        STA RPT_STATE
        RET
RPT_RUNNING:
        LDA RPT_STATE
        CPI 09H
        JZ RPT_FINISH
        LDA TX_PENDING
        CPI 00H
        RZ
        MVI A,00H
        STA TX_PENDING
        LDA RPT_STATE
        INR A
        STA RPT_STATE
        CPI 09H
        JZ X_1940
        JMP RPT_NEXT_ITEM
RPT_FINISH:
        MVI A,0FEH
        STA RPT_STATE
        RET
RPT_NEXT_ITEM:
        LDA RPT_STATE
        CPI 00H
        JNZ RPT_ITEM_N
        LDA SLOT_FLAGS
        ANI 50H                     ; 'P'
        CPI 50H                     ; 'P'
        RNZ
        LDA SLOT_FLAGS
        JMP RPT_FORMAT
RPT_ITEM_N:
        MOV C,A
        MVI B,00H
        LXI H,SLOT_FLAGS
        DAD B
        MOV A,M
        ANI 0D0H
        CPI 0D0H
        MOV A,M
        RNZ
RPT_FORMAT:
        LDA RPT_STATE
        LXI H,SLOTREC_3
        CALL MUL9_INDEX             ; HL = SLOTREC_3 + 9 * item
        CALL X_189B
        CALL X_1878
        LDA RPT_STATE
        CPI 00H
        JNZ RPT_ITEM_OFS
        LXI H,GRI_BCD_HI
        JMP X_1804
RPT_ITEM_OFS:
        LXI H,0FF56H                ; operand high byte is at 1800 in the undumped half: real value unknown (dump shows 0FFH)
; ---- 1801-1FFF: unprogrammed / not dumped (reads as 0FFH) ----
